{
  "name": "@bybrawe/opencode-queue-manager",
  "version": "0.3.5",
  "description": "OpenCode v2 Desktop and TUI prompt queue manager: batch tasks, reorder drafts by drag-and-drop, 20-language Desktop interface and safe plugin installer.",
  "type": "module",
  "license": "MIT",
  "homepage": "https://github.com/ByBrawe/OpenCode-Queue-Manager#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ByBrawe/OpenCode-Queue-Manager.git"
  },
  "bugs": {
    "url": "https://github.com/ByBrawe/OpenCode-Queue-Manager/issues"
  },
  "keywords": [
    "opencode",
    "opencode-v2",
    "opencode-plugin",
    "opencode-queue",
    "queue-manager",
    "ai-coding-agent",
    "prompt-queue",
    "batch-prompts",
    "desktop",
    "tui",
    "deepseek",
    "windows",
    "macos",
    "linux",
    "multilingual",
    "internationalization",
    "i18n",
    "rtl"
  ],
  "publishConfig": {
    "access": "public"
  },
  "files": [
    "bin/",
    "src/",
    "dist/",
    "README.md",
    "LICENSE"
  ],
  "exports": {
    ".": "./src/index.mjs",
    "./tui": "./src/tui.ts",
    "./gui-experimental": "./dist/gui-experimental.cjs"
  },
  "dependencies": {
    "@opencode/plugin": "latest"
  },
  "scripts": {
    "build": "node scripts/build-gui.mjs",
    "check": "node --check dist/gui-experimental.cjs && node --check src/gui-experimental.mjs && node --check src/queue-core.mjs && node --check src/installer/jsonc-config.mjs && node --check src/installer/cli.mjs && node --check bin/opencode-queue-manager.mjs && node --check scripts/prepare-npm-release.mjs && node --check src/release/version.mjs && node --check src/i18n/index.mjs && node --check src/i18n/labels.mjs && node --check src/i18n/details.mjs",
    "test": "node --test",
    "verify": "npm run build && npm run check && npm test",
    "prepack": "npm run verify"
  },
  "engines": {
    "node": ">=20"
  },
  "bin": {
    "opencode-queue-manager": "./bin/opencode-queue-manager.mjs"
  },
  "releaseCommit": "fed73d43f42392e553a9a032e1a88f99bbdfe50a",
  "devDependencies": {
    "solid-js": "^1.9.12",
    "vite": "^7.3.7",
    "vite-plugin-solid": "^2.11.0"
  }
}
